#include "App.hpp"
#include "core/Shortcuts.hpp"

#include <vector>
#include "Shell.hpp"
#include "Appearance.hpp"
#include "Log.hpp"

#include <gtkmm/icontheme.h>
#include <gtkmm/cssprovider.h>
#include <gtkmm/settings.h>
#include <gtkmm/stylecontext.h>
#include <gdkmm/display.h>

// The RESOURCE-PIPELINE paradigm's build-side seam. The app logo ships in a
// compiled-in GResource bundle (resources/kaflip.gresource.xml -> kaflip-resources.c,
// generated by glib-compile-resources). Declared extern "C" because that
// generated source compiles as C -- so its getter has C linkage and there's no
// generated header to include or keep in sync. (docs/resources-and-dialog-lifetime.md)
extern "C" GResource* kaflip_resources_get_resource(void);

namespace kaflip {

Glib::RefPtr<App> App::create() {
    log::init();   // area loggers up before anything logs
    return Glib::make_refptr_for_instance(new App());
}

// s002: HANDLES_OPEN, so files on the command line (and from the desktop
// file's %F) arrive in on_open instead of being refused.
App::App() : Gtk::Application("io.github.scott8420.Kaflip", Gio::Application::Flags::HANDLES_OPEN) {}

// The SHORTCUT-REGISTRY paradigm's other consumer. Accelerators are an
// application-scope concern (they survive window construction order), so they
// bind here -- and they are driven from the pure core::shortcut_registry(), the
// same list ShortcutsDialog documents from. Register a shortcut once THERE and
// both the key and its advertised row follow; there is no second list to update
// and therefore nothing to drift. Doc-only rows (gestures) carry no action and
// are skipped -- they document without binding.
void App::on_startup() {
    Gtk::Application::on_startup();
    for (const auto& s : core::shortcut_registry()) {
        if (s.action.empty() || s.accels.empty()) continue;
        std::vector<Glib::ustring> accels(s.accels.begin(), s.accels.end());
        set_accels_for_action(s.action, accels);
    }
}

void App::on_activate() {
    ensure_shell();
    m_shell->present();
}

// s002: open the first file given (one window, one book for now). Further
// files are logged, not silently dropped.
void App::on_open(const type_vec_files& files, const Glib::ustring&) {
    ensure_shell();
    m_shell->present();
    if (files.empty()) return;
    m_shell->open_book(files.front()->get_path());
    if (files.size() > 1)
        if (auto lg = log::get(log::Area::App))
            lg->warn("{} files given; opened the first, ignored the rest", files.size());
}

void App::ensure_shell() {
    if (m_shell) return;
    // ── THE DESKTOP'S LIGHT/DARK PREFERENCE, FIRST, BEFORE ANY WINDOW ───────
    // GTK4 does not follow it on its own and Kaflip does not link libadwaita,
    // so the app has to ask (see Appearance.hpp). Ahead of `new Shell()` on
    // purpose: the difference between starting dark and starting light and
    // repainting.
    //
    // It also has to be ahead of the icon theme work below. The logo is a
    // SYMBOLIC icon, which GTK recolours to the theme foreground -- so it
    // inherits the answer to this question rather than carrying an opinion of
    // its own, and that is exactly why the bundle ships one symbolic SVG
    // instead of a light and a dark PNG.
    appearance::follow_system();
    // s004: Ka-flip wears Trails' skin, which is its own dark, always
    // (resources/kaflip.css). GTK's dark variant is asked for AFTER
    // follow_system so menus, popovers, dialogs and the file chooser match it.
    // Appearance.* stays compiled for a later "match the desktop" setting.
    if (auto settings = Gtk::Settings::get_default())
        settings->property_gtk_application_prefer_dark_theme() = true;

    // Register the compiled-in bundle and point the icon theme at its icon
    // prefix, so set_icon_name("kaflip-logo-symbolic") resolves out of the binary
    // and GTK recolours it to the theme foreground -- no icon on the user's disk.
    // NB: add_resource_path gets .../icons; GTK appends scalable/apps/ itself.
    g_resources_register(kaflip_resources_get_resource());
    if (auto display = Gdk::Display::get_default()) {
        auto icons = Gtk::IconTheme::get_for_display(display);
        icons->add_resource_path("/io/github/scott8420/Kaflip/icons");

        // s004: the skin, out of the same bundle. APPLICATION priority so it
        // wins over the theme but a user's gtk.css can still override.
        auto css = Gtk::CssProvider::create();
        css->signal_parsing_error().connect(
            [](const Glib::RefPtr<const Gtk::CssSection>& sec, const Glib::Error& e) {
                if (auto lg = log::get(log::Area::App))
                    lg->warn("kaflip.css:{}: {}", sec->get_start_location().get_lines() + 1, e.what());
            });
        css->load_from_resource("/io/github/scott8420/Kaflip/kaflip.css");
        Gtk::StyleContext::add_provider_for_display(display, css,
                                                    GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    }

    m_shell = new Shell();       // lifetime owned by the application
    add_window(*m_shell);
    m_shell->build_ui();
    if (auto lg = log::get(log::Area::App)) lg->info("Kaflip activated");
}

}  // namespace kaflip
